{
    "fun_req_summary": "用户管理功能实现安全可靠的用户注册与登录流程，包括输入合法性校验、用户名唯一性检查、JWT令牌生成与时效控制、以及基于失败次数的账户锁定机制。",
    "input_stream_desc": [
        "用户名（3-20字符）",
        "邮箱（符合RFC 5322基础语法格式）",
        "密码（8-32字符）"
    ],
    "fun_items": [
        {
            "fun_id": "TR-UM-RegLogin-001",
            "handling": "验证用户名长度是否在3-20字符范围内，若不符合则拒绝注册/登录请求。"
        },
        {
            "fun_id": "TR-UM-RegLogin-002",
            "handling": "验证密码长度是否在8-32字符范围内，若不符合则拒绝注册/登录请求。"
        },
        {
            "fun_id": "TR-UM-RegLogin-003",
            "handling": "验证邮箱格式是否符合标准RFC 5322规范（含@符号、域名结构等基本语法），若不符合则拒绝注册/登录请求。"
        },
        {
            "fun_id": "TR-UM-RegLogin-004",
            "handling": "检查待注册用户名是否已在系统中存在；若已存在，则拒绝注册并返回唯一性冲突提示。"
        },
        {
            "fun_id": "TR-UM-RegLogin-005",
            "handling": "用户成功登录后，生成符合RFC 7519标准的JWT令牌，其中payload包含user_id、username及exp（当前时间+86400秒），签名算法为HS256。"
        },
        {
            "fun_id": "TR-UM-RegLogin-006",
            "handling": "JWT令牌有效期严格设为86400秒（24小时），且exp字段值与服务器当前UTC时间戳之差精确等于86400。"
        },
        {
            "fun_id": "TR-UM-RegLogin-007",
            "handling": "同一用户名连续登录失败达5次后，该账户被锁定30分钟（1800秒），期间所有登录请求均立即返回锁定状态响应，不进行密码校验。"
        },
        {
            "fun_id": "TR-UM-RegLogin-008",
            "handling": "账户锁定计时从第5次失败登录完成时刻开始，以服务端高精度单调时钟（如HAL_GetTick()或类似机制）为基准，确保超时判定准确。"
        }
    ],
    "output_stream_desc": [
        "user_id（整型或字符串格式唯一标识符）",
        "username（与输入一致的注册用户名）",
        "token（符合RFC 7519标准的JWT字符串，HS256签名）",
        "expires_in（固定值86400秒）"
    ]
}

